const sd = $getWorkflowStaticData('global');
if ($json.todayKey) sd.daily_calendar_last_date = $json.todayKey;

// Berlin time
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));

const toFaDigits = (s) => String(s).replace(/\d/g, (d) => '۰۱۲۳۴۵۶۷۸۹'[+d]);

// Jalali (native Intl)
const jalaliFormatter = new Intl.DateTimeFormat('fa-IR-u-ca-persian', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric'
});
const jParts = jalaliFormatter.formatToParts(now);
const jWeekday = jParts.find(p => p.type === 'weekday')?.value;
const jDay = jParts.find(p => p.type === 'day')?.value;
const jMonth = jParts.find(p => p.type === 'month')?.value;
const jYear = jParts.find(p => p.type === 'year')?.value;

const jalaliDate = `${jWeekday} ${toFaDigits(jDay)} ${jMonth} ${toFaDigits(jYear)}`;

// Gregorian month names (FA)
const monthsFa = ['ژانویه','فوریه','مارس','آوریل','می','ژوئن','ژوئیه','اوت','سپتامبر','اکتبر','نوامبر','دسامبر'];
const gDay = now.getDate();
const gMonthName = monthsFa[now.getMonth()];
const gYear = now.getFullYear();
const gregorianDate = `${toFaDigits(gDay)} ${gMonthName} ${toFaDigits(gYear)}`;

// Time HH:mm
const hours = toFaDigits(String(now.getHours()).padStart(2,'0'));
const minutes = toFaDigits(String(now.getMinutes()).padStart(2,'0'));
const timeLine = `${hours}:${minutes}`;

// Holidays
const holidaysToday = Array.isArray($json.holidaysToday) ? $json.holidaysToday : [];
let holidayBlock = '';
if (holidaysToday.length) {
  const lines = holidaysToday.map(h =>
    h.isNational ? `• ${h.localName} (سراسری)` : `• ${h.localName} (ویژهٔ ایالت‌ها: ${h.states})`
  ).join('\n');
  holidayBlock = `\n📌 تعطیلات/مناسبت‌های امروز:\n${lines}`;
}

// Place
if (!$json.place) throw new Error("place missing (check Merge inputs)");
const { name, city } = $json.place;

// Binary
const binary = $input.first().binary;

// Caption
const caption =
` ☀️ سلام، صبح بخیر

🏛 تصویر روز
${name} — ${city}

📅 ${jalaliDate} | ${gregorianDate}
⏰ ${timeLine} — به وقت برلین${holidayBlock}

با ما همراه باشید با تازه‌ترین اخبار آلمان و جهان

@German_news_fa
https://x.com/GermanNewsFa`;

return [{
  json: { caption: `\u202B${caption}\u202C` },
  binary
}];

