// Code node v2 — Post-process FA (digits, spacing, punctuation, zwnj) — FIXED
const items = $input.all();

const toPersianDigits = s => s.replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[+d]);

function normalizePunctuation(s=''){
  return s
    .replace(/ ,/g,'، ')
    .replace(/ ?\.\.\./g,'…')
    .replace(/\s*-\s*/g,' - ')
    .replace(/\s*:\s*/g,': ')
    .replace(/\s*؛\s*/g,'؛ ')
    .replace(/ ?! ?/g,'! ')
    .replace(/ \?/g,'؟ ')
    .replace(/\s+/g,' ')
    .replace(/\s+([»”\)\]])/g,'$1')
    .replace(/([«“\(\[])\s+/g,'$1')
    .trim();
}

function fixMibashad(s=''){ return s.replace(/\bمی\s?باشد\b/g,'است'); }

function zwnj(s=''){
  // URLها را دست نزن
  if (/https?:\/\//.test(s)) return s;
  return s
    .replace(/\b(ن?می)\s+/g,'$1\u200c') // می رود → می‌رود
    .replace(/\s+(تر|ترین|ها|های|هایی|ای|ام|ات|اش|اند)\b/g,'\u200c$1');
}

return items.map(it=>{
  const j = it.json || {};
  const proc = (t='') => normalizePunctuation(zwnj(fixMibashad(toPersianDigits(t.trim()))));
  j.title_fa  = proc(j.title_fa || '');
  j.teaser_fa = proc(j.teaser_fa || '');
  return { json: j };
});

