// ساخت متن توییت
function buildTweetText(title, teaser, link) {
  const MAX = 280;

  // تمیز کردن متن
  const clean = (s = '') =>
    s.toString().replace(/\s+/g, ' ').trim();

  const t = clean(title);
  const p = clean(teaser);

  // تیتر + یک خط خالی + پاراگراف اول
  let base = t;
  if (p) base += (base ? '\n\n' : '') + p;

  // توییتر هر لینک را حدود ۲۳ کاراکتر حساب می‌کند (+ ۱ کاراکتر برای \n)
  const URL_RESERVED = 24; // 23 for t.co + '\n'
  const pad = link ? URL_RESERVED : 0;
  const room = MAX - pad;

  if (room <= 0) return link || '';

  if (base.length <= room) {
    return link ? `${base}\n${link}` : base;
  }

  // کوتاه کردن روی مرز کلمه
  const cut = base.slice(0, room - 1);
  let idx = cut.lastIndexOf(' ');
  if (idx < 40) idx = room - 1;
  const short = cut.slice(0, idx) + '…';

  return link ? `${short}\n${link}` : short;
}

