function toStr(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
}

function decodeEntities(s = '') {
  return s
    .replace(/\\u003c/g, '<')
    .replace(/\\u003e/g, '>')
    .replace(/\\u0026/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

function stripTags(html = '') {
  return decodeEntities(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractJsonLdArticleBody(html = '') {
  const scripts = [...html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];

  for (const m of scripts) {
    let raw = decodeEntities(m[1]).trim();

    try {
      const parsed = JSON.parse(raw);
      const arr = Array.isArray(parsed) ? parsed : [parsed];

      const stack = [...arr];
      while (stack.length) {
        const obj = stack.shift();
        if (!obj || typeof obj !== 'object') continue;

        const type = obj['@type'];
        const isArticle =
          type === 'Article' ||
          type === 'NewsArticle' ||
          (Array.isArray(type) && type.some(t => ['Article', 'NewsArticle'].includes(t)));

        if (isArticle) {
          const body =
            obj.articleBody ||
            obj.description ||
            obj.headline ||
            '';

          if (body && String(body).length > 200) {
            return stripTags(String(body));
          }
        }

        for (const v of Object.values(obj)) {
          if (Array.isArray(v)) stack.push(...v);
          else if (v && typeof v === 'object') stack.push(v);
        }
      }
    } catch {}
  }

  return '';
}

function extractParagraphs(html = '') {
  let s = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<iframe[\s\S]*?<\/iframe>/gi, ' ');

  const pMatches = [...s.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)]
    .map(m => stripTags(m[1]))
    .map(x => x.replace(/\s+/g, ' ').trim())
    .filter(x => x.length > 35)
    .filter(x => !/(anzeige|werbung|newsletter|podcast|mehr zum thema|lesen sie auch|teilen|kommentare|cookie|datenschutz|abo|login|registrieren)/i.test(x));

  return [...new Set(pMatches)].join('\n\n').slice(0, 12000).trim();
}

function extractMetaImage(html = '') {
  const patterns = [
    /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i,
    /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i,
    /<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["']/i,
    /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']twitter:image["']/i,
  ];

  for (const re of patterns) {
    const m = html.match(re);
    if (m?.[1]) return decodeEntities(m[1].trim());
  }
  return '';
}

function absolutize(url = '', base = '') {
  if (!url) return '';
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('//')) return 'https:' + url;
  try {
    return new URL(url, base).toString();
  } catch {
    return url;
  }
}

